function filterCards(){let input=document.getElementById("searchInput").value.toLowerCase();let sections=document.querySelectorAll("section");sections.forEach(section=>{let cards=section.querySelectorAll(".card");let visibleCount=0;cards.forEach(card=>{let name=card.getAttribute("data-name");if(!input||name.includes(input)){card.style.display="block";visibleCount++;}else{card.style.display="none";}});section.style.display=visibleCount>0?"block":"none";});}
function clearSearch(){document.getElementById("searchInput").value="";filterCards();}
const modal=document.getElementById('imageModal');const modalImg=document.getElementById('modalImg');const modalCaption=document.getElementById('modalCaption');const modalDelito=document.getElementById('modalDelito');const modalEdad=document.getElementById('modalEdad');const modalDNICE=document.getElementById('modalDNICE');const modalSexo=document.getElementById('modalSexo');const modalLugar=document.getElementById('modalLugar');const modalFecha=document.getElementById('modalFecha');const modalSade=document.getElementById('modalSade');const modalRecompensa=document.getElementById('modalRecompensa');const modalReincidente=document.getElementById('modalReincidente');function openModal(imgUrl,name,delito,edad,dnice,sexo,lugar,fecha_formateada,sade,recompensa,reincidente){modal.style.display='flex';modalImg.src=imgUrl;modalImg.alt=name.replace(/\.[^/.]+$/,"");modalCaption.textContent=name.replace(/\.[^/.]+$/,"").replaceAll("_"," ");modalDelito.textContent=delito?"Delito: "+delito:"";modalEdad.textContent=edad||"-";modalDNICE.textContent=dnice||"-";modalSexo.textContent=sexo||"-";modalLugar.textContent=lugar||"-";modalFecha.textContent=fecha_formateada||"-";modalSade.textContent=sade||"-";modalRecompensa.textContent=recompensa||"S/ -";modalReincidente.textContent=reincidente||"-";}
function closeModal(){modal.style.display='none';modalImg.src='';modalCaption.textContent='';modalDelito.textContent='';modalEdad.textContent='';modalDNICE.textContent='';modalSexo.textContent='';modalLugar.textContent='';modalFecha.textContent='';modalSade.textContent='';modalRecompensa.textContent='S/ -';modalReincidente.textContent='';}
modal.addEventListener('click',function(e){if(e.target===this)closeModal();});document.addEventListener('keydown',function(e){if(e.key==='Escape')closeModal();});